from hashlib import sha256
from decimal import Decimal
import json
from uteki.agents.data_query.coordinator import _verify_manifest
E=Path('experiments/agent_design/2026-10-09-e1-benchmark-v1');out=E/'evaluation-only/reviews/E1-05-sonnet-focus-recovery-r1';old=E/'runs/E1-05-sonnet-focus-recovery-r1';new=E/'runs/E1-05-sonnet-context-review-r1'
